package io.github.nevaseme.plandmk1.buildings

import java.io.DataInputStream
import java.io.InputStream
import java.util.zip.GZIPInputStream

/** Normalization is generated by the shared JS contract at build time, never on the UI thread. */
fun readPreparedAddresses(input:InputStream,code:String):List<AddressCandidate> = DataInputStream(GZIPInputStream(input).buffered()).use { r ->
 require(r.readInt()==0x50445331) {"Unsupported address package"}
 val count=r.readInt();require(count in 0..1_000_000)
 fun text():String {val n=r.readInt();require(n in 0..65536);return ByteArray(n).also{r.readFully(it)}.toString(Charsets.UTF_8)}
 List(count){
  val id=text();val address=text();val lon=r.readDouble();val lat=r.readDouble()
  val precision=text().intern();val match=text().intern();val source=text().ifEmpty{null}?.intern();val version=text().ifEmpty{null}?.intern();val normalized=text()
  AddressCandidate(id,address,lon,lat,precision,normalized,match,source,version,code)
 }
}
